changeSet.sql:
ALTER TABLE selector ENABLE ROW LEVEL SECURITY;
ALTER TABLE selector FORCE ROW LEVEL SECURITY;

DO $$ BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM pg_policies
        WHERE schemaname = current_schema()
          AND tablename = 'selector'
          AND policyname = 'selector_tenant_isolation'
    ) THEN
        EXECUTE 'CREATE POLICY selector_tenant_isolation ON selector '
             || 'USING (tenant_id = current_setting(''app.tenant_id'', true)::uuid) '
             || 'WITH CHECK (tenant_id = current_setting(''app.tenant_id'', true)::uuid)';
    END IF;
END $$;

